      628: 
      629:   amt = sec->reloc_count * relsz;
      630:   if (external_relocs == NULL)
      631:     {
      632:       free_external = (bfd_byte *) bfd_malloc (amt);
      633:       if (free_external == NULL)
      634: 	goto error_return;
      635:       external_relocs = free_external;
